import math
import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry conv3d_ncdhw(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 N,
    .param .u32 C_in,
    .param .u32 C_out,
    .param .u32 D_in,
    .param .u32 H_in,
    .param .u32 W_in,
    .param .u32 D_out,
    .param .u32 H_out,
    .param .u32 W_out,
    .param .u32 Kd,
    .param .u32 Kh,
    .param .u32 Kw,
    .param .u32 strideD,
    .param .u32 strideH,
    .param .u32 strideW,
    .param .u32 padD,
    .param .u32 padH,
    .param .u32 padW,
    .param .u32 dilD,
    .param .u32 dilH,
    .param .u32 dilW,
    .param .u32 groups,
    .param .u32 has_bias
)
{
    .reg .pred p, p0;
    .reg .b32 rN, rCin, rCout, rDin, rHin, rWin, rDout, rHout, rWout;
    .reg .b32 rKd, rKh, rKw;
    .reg .b32 rStrideD, rStrideH, rStrideW, rPadD, rPadH, rPadW, rDilD, rDilH, rDilW, rGroups, rHasBias;
    .reg .b32 rw, rh, rtx, rty, rbx, rby, rbdx, rbdy;
    .reg .b64 px, pw, pb, py;
    .reg .b32 rci, rtmp32;
    .reg .b64 offb;

    ld.param.u64 px, [x_ptr];
    ld.param.u64 pw, [w_ptr];
    ld.param.u64 pb, [b_ptr];
    ld.param.u64 py, [y_ptr];

    ld.param.u32 rN,      [N];
    ld.param.u32 rCin,    [C_in];
    ld.param.u32 rCout,   [C_out];
    ld.param.u32 rDin,    [D_in];
    ld.param.u32 rHin,    [H_in];
    ld.param.u32 rWin,    [W_in];
    ld.param.u32 rDout,   [D_out];
    ld.param.u32 rHout,   [H_out];
    ld.param.u32 rWout,   [W_out];
    ld.param.u32 rKd,     [Kd];
    ld.param.u32 rKh,     [Kh];
    ld.param.u32 rKw,     [Kw];
    ld.param.u32 rStrideD,[strideD];
    ld.param.u32 rStrideH,[strideH];
    ld.param.u32 rStrideW,[strideW];
    ld.param.u32 rPadD,   [padD];
    ld.param.u32 rPadH,   [padH];
    ld.param.u32 rPadW,   [padW];
    ld.param.u32 rDilD,   [dilD];
    ld.param.u32 rDilH,   [dilH];
    ld.param.u32 rDilW,   [dilW];
    ld.param.u32 rGroups, [groups];
    ld.param.u32 rHasBias,[has_bias];

    mov.u32 rtx, %tid.x;
    mov.u32 rty, %tid.y;
    mov.u32 rbx, %ctaid.x;
    mov.u32 rby, %ctaid.y;
    mov.u32 rbdx, %ntid.x;
    mov.u32 rbdy, %ntid.y;

    mad.lo.u32 rw, rbx, rbdx, rtx; // w_out
    mad.lo.u32 rh, rby, rbdy, rty; // h_out

    // bounds check on w_out and h_out
    setp.ge.u32 p, rw, rWout;
    @p bra DONE;
    setp.ge.u32 p, rh, rHout;
    @p bra DONE;

    // Decode blockIdx.z into (d_out, n, co): k = d_out*(N*C_out) + n*C_out + co
    .reg .b32 rk, rco, rtmp, rn, rdout;
    mov.u32 rk, %ctaid.z;
    rem.u32 rco,  rk, rCout;
    div.u32 rtmp, rk, rCout;
    rem.u32 rn,   rtmp, rN;
    div.u32 rdout,rtmp, rN;

    // group partitions
    .reg .b32 rout_per_g, rin_per_g, rgroup_id;
    div.u32 rout_per_g, rCout, rGroups;
    div.u32 rin_per_g,  rCin,  rGroups;
    div.u32 rgroup_id,  rco,   rout_per_g;

    // compute input base coords (signed)
    .reg .s32 sd0, sh0, sw0;
    .reg .s32 srdout, srh, srw, sStrideD, sStrideH, sStrideW, sPadD, sPadH, sPadW, sDilD, sDilH, sDilW, sDin, sHin, sWin;
    cvt.s32.u32 srdout, rdout;
    cvt.s32.u32 srh,    rh;
    cvt.s32.u32 srw,    rw;

    cvt.s32.u32 sStrideD, rStrideD;
    cvt.s32.u32 sStrideH, rStrideH;
    cvt.s32.u32 sStrideW, rStrideW;
    cvt.s32.u32 sPadD,    rPadD;
    cvt.s32.u32 sPadH,    rPadH;
    cvt.s32.u32 sPadW,    rPadW;
    cvt.s32.u32 sDilD,    rDilD;
    cvt.s32.u32 sDilH,    rDilH;
    cvt.s32.u32 sDilW,    rDilW;
    cvt.s32.u32 sDin,     rDin;
    cvt.s32.u32 sHin,     rHin;
    cvt.s32.u32 sWin,     rWin;

    mul.lo.s32 sd0, srdout, sStrideD;
    sub.s32    sd0, sd0,    sPadD;
    mul.lo.s32 sh0, srh,    sStrideH;
    sub.s32    sh0, sh0,    sPadH;
    mul.lo.s32 sw0, srw,    sStrideW;
    sub.s32    sw0, sw0,    sPadW;

    // accumulator init (with bias if present)
    .reg .f32 facc, fx, fw, fb;
    mov.f32 facc, 0f00000000;
    setp.ne.u32 p0, rHasBias, 0;
    @!p0 bra BIAS_SKIP;
    mul.wide.u32 offb, rco, 4;
    add.s64 offb, pb, offb;
    ld.global.f32 fb, [offb];
    mov.f32 facc, fb;
    BIAS_SKIP:
    // end bias init

    // loops
    .reg .b32 rkd, rkh, rkw, rci_g;
    .reg .s32 sid, sih, siw, tmp_s32;
    .reg .b64 offx, offw, offy, t64a, t64b;

    mov.u32 rkd, 0;
KD_LOOP:
    setp.ge.u32 p, rkd, rKd;
    @p bra KD_END;

    mul.lo.s32 tmp_s32, rkd, sDilD;
    add.s32    sid, sd0, tmp_s32;
    setp.lt.s32 p, sid, 0;
    @p bra KD_CONT;
    setp.ge.s32 p, sid, sDin;
    @p bra KD_CONT;

    mov.u32 rkh, 0;
KH_LOOP:
    setp.ge.u32 p, rkh, rKh;
    @p bra KH_END;

    mul.lo.s32 tmp_s32, rkh, sDilH;
    add.s32    sih, sh0, tmp_s32;
    setp.lt.s32 p, sih, 0;
    @p bra KH_CONT;
    setp.ge.s32 p, sih, sHin;
    @p bra KH_CONT;

    mov.u32 rkw, 0;
KW_LOOP:
    setp.ge.u32 p, rkw, rKw;
    @p bra KW_END;

    mul.lo.s32 tmp_s32, rkw, sDilW;
    add.s32    siw, sw0, tmp_s32;
    setp.lt.s32 p, siw, 0;
    @p bra KW_CONT;
    setp.ge.s32 p, siw, sWin;
    @p bra KW_CONT;

    mov.u32 rci_g, 0;
CI_LOOP:
    setp.ge.u32 p, rci_g, rin_per_g;
    @p bra CI_END;

    // ci = rgroup_id * rin_per_g + rci_g
    mul.lo.u32 rtmp32, rgroup_id, rin_per_g;
    add.u32    rci, rtmp32, rci_g;

    // x offset: ((((n*C_in + ci)*D_in + sid)*H_in + sih)*W_in + siw) * 4
    mul.wide.u32 offx, rn, rCin;             // n * C_in
    cvt.u64.u32 t64a, rci;
    add.u64     offx, offx, t64a;            // + ci
    cvt.u64.u32 t64a, rDin;
    mul.lo.u64  offx, offx, t64a;            // * D_in
    cvt.s64.s32 t64a, sid;
    add.s64     offx, offx, t64a;            // + sid
    cvt.u64.u32 t64a, rHin;
    mul.lo.u64  offx, offx, t64a;            // * H_in
    cvt.s64.s32 t64a, sih;
    add.s64     offx, offx, t64a;            // + sih
    cvt.u64.u32 t64a, rWin;
    mul.lo.u64  offx, offx, t64a;            // * W_in
    cvt.s64.s32 t64a, siw;
    add.s64     offx, offx, t64a;            // + siw
    shl.b64     offx, offx, 2;               // * 4 (bytes)
    add.s64     offx, px, offx;
    ld.global.f32 fx, [offx];

    // w offset: ((((co)*rin_per_g + rci_g)*Kd + rkd)*Kh + rkh)*Kw + rkw
    mul.wide.u32 offw, rco, rin_per_g;       // co * rin_per_g
    cvt.u64.u32 t64a, rci_g;
    add.u64     offw, offw, t64a;            // + rci_g
    cvt.u64.u32 t64a, rKd;
    mul.lo.u64  offw, offw, t64a;            // * Kd
    cvt.u64.u32 t64a, rkd;
    add.u64     offw, offw, t64a;            // + rkd
    cvt.u64.u32 t64a, rKh;
    mul.lo.u64  offw, offw, t64a;            // * Kh
    cvt.u64.u32 t64a, rkh;
    add.u64     offw, offw, t64a;            // + rkh
    cvt.u64.u32 t64a, rKw;
    mul.lo.u64  offw, offw, t64a;            // * Kw
    cvt.u64.u32 t64a, rkw;
    add.u64     offw, offw, t64a;            // + rkw
    shl.b64     offw, offw, 2;               // * 4
    add.s64     offw, pw, offw;
    ld.global.f32 fw, [offw];

    fma.rn.f32  facc, fx, fw, facc;

    add.u32 rci_g, rci_g, 1;
    bra CI_LOOP;
CI_END:

KW_CONT:
    add.u32 rkw, rkw, 1;
    bra KW_LOOP;
KW_END:

KH_CONT:
    add.u32 rkh, rkh, 1;
    bra KH_LOOP;
KH_END:

KD_CONT:
    add.u32 rkd, rkd, 1;
    bra KD_LOOP;
KD_END:

    // y offset: ((((n*C_out + co)*D_out + rdout)*H_out + rh)*W_out + rw) * 4
    mul.wide.u32 offy, rn, rCout;            // n * C_out
    cvt.u64.u32 t64a, rco;
    add.u64     offy, offy, t64a;            // + co
    cvt.u64.u32 t64a, rDout;
    mul.lo.u64  offy, offy, t64a;            // * D_out
    cvt.u64.u32 t64a, rdout;
    add.u64     offy, offy, t64a;            // + d_out
    cvt.u64.u32 t64a, rHout;
    mul.lo.u64  offy, offy, t64a;            // * H_out
    cvt.u64.u32 t64a, rh;
    add.u64     offy, offy, t64a;            // + h_out
    cvt.u64.u32 t64a, rWout;
    mul.lo.u64  offy, offy, t64a;            // * W_out
    cvt.u64.u32 t64a, rw;
    add.u64     offy, offy, t64a;            // + w_out
    shl.b64     offy, offy, 2;               // * 4
    add.s64     offy, py, offy;
    st.global.f32 [offy], facc;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv3d_ncdhw")

class ModelNew(nn.Module):
    """
    Performs a standard 3D convolution operation with square input and square kernel using a single custom PTX kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        assert isinstance(kernel_size, int), "kernel_size must be an int (square kernel)"
        assert isinstance(stride, int), "stride must be an int"
        assert isinstance(padding, int), "padding must be an int"
        assert isinstance(dilation, int), "dilation must be an int"
        assert in_channels % groups == 0, "in_channels must be divisible by groups"
        assert out_channels % groups == 0, "out_channels must be divisible by groups"

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.bias_flag = bias

        weight = torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size, kernel_size)
        self.weight = nn.Parameter(weight)
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()

    def reset_parameters(self):
        # Match torch.nn.Conv3d default initialization
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = (self.in_channels // self.groups) * (self.kernel_size ** 3)
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, +bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "Only float32 is supported"
        N, Cin, Din, Hin, Win = x.shape
        assert Cin == self.in_channels

        k = self.kernel_size
        s = self.stride
        p = self.padding
        d = self.dilation
        g = self.groups

        Kd = Kh = Kw = k
        strideD = strideH = strideW = s
        padD = padH = padW = p
        dilD = dilH = dilW = d

        # Output dimensions (PyTorch conv formula)
        def out_dim(in_sz, pad, dil, ksz, stride):
            return (in_sz + 2 * pad - dil * (ksz - 1) - 1) // stride + 1

        Dout = out_dim(Din, padD, dilD, Kd, strideD)
        Hout = out_dim(Hin, padH, dilH, Kh, strideH)
        Wout = out_dim(Win, padW, dilW, Kw, strideW)

        y = torch.empty((N, self.out_channels, Dout, Hout, Wout), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()

        # Safe bias pointer even if bias is None
        bias_tensor = self.bias if self.bias is not None else y.new_empty(1)

        # Grid and block configuration
        block_x = 8
        block_y = 8
        block_z = 1
        grid_x = (Wout + block_x - 1) // block_x
        grid_y = (Hout + block_y - 1) // block_y
        grid_z = int(N * self.out_channels * Dout)

        module.launch(
            "conv3d_ncdhw",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, block_z),
            arguments=[
                x, self.weight, bias_tensor, y,
                u32(N), u32(Cin), u32(self.out_channels),
                u32(Din), u32(Hin), u32(Win),
                u32(Dout), u32(Hout), u32(Wout),
                u32(Kd), u32(Kh), u32(Kw),
                u32(strideD), u32(strideH), u32(strideW),
                u32(padD), u32(padH), u32(padW),
                u32(dilD), u32(dilH), u32(dilW),
                u32(g),
                u32(1 if self.bias is not None else 0),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

