    ld.param.u32 rKh,     [Kh];
    ld.param.u32 rKw,     [Kw];
    ld.param.u32 rStrideD,[strideD];
    ld.param.u32 rStrideH,[strideH];
    ld.param.u32 rStrideW,[strideW];
    ld.param.u32 rPadD,   [padD];
    ld.param.u32 rPadH,   [padH];
    ld.param.u32 rPadW,   [padW];
    ld.param.u32 rDilD,   [dilD];
    ld.param.u32 rDilH,   [dilH];
